<section class="admin-panel admin-table-panel"><div class="table-toolbar table-toolbar-stack"><form class="admin-search" method="get" action="<?= e(admin_url('/messages')) ?>"><label class="sr-only" for="message-search">جستجوی پیام‌ها</label><input id="message-search" type="search" name="q" value="<?= e($query) ?>" placeholder="جستجوی نام، کسب‌وکار یا ایمیل"><select name="type" aria-label="فیلتر بر اساس نوع درخواست"><option value="">همه انواع پیام‌ها</option><option value="wholesale" <?= $type === 'wholesale' ? 'selected' : '' ?>>درخواست عمده‌فروشی</option><option value="contact" <?= $type === 'contact' ? 'selected' : '' ?>>تماس با ما</option></select><button type="submit">فیلتر ↗</button></form><span class="toolbar-meta">نمایش <?= e(count($messages['items'] ?? array())) ?> از <?= e($messages['total'] ?? 0) ?></span></div><?php if (empty($messages['items'])): ?><div class="empty-state table-empty"><span>◌</span><strong>هیچ درخواستی یافت نشد</strong><p>در حالت دیتابیس فعال (MySQL)، پیام‌های ثبت‌شده در فرم‌های تماس و عمده‌فروشی وب‌سایت در اینجا ظاهر خواهند شد.</p></div><?php else: ?><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>فرستنده</th><th>نوع پیام</th><th>منطقه/کشور</th><th>تاریخ دریافت</th><th><span class="sr-only">عملیات</span></th></tr></thead><tbody><?php foreach ($messages['items'] as $message): ?><tr><td><div class="table-primary"><a href="<?= e(admin_url('/messages/view/' . (int) $message['id'])) ?>"><?= e($message['name']) ?></a><small><?= e($message['business_name'] ?: $message['email']) ?></small></div></td><td><span class="message-type <?= e($message['message_type']) ?>"><?= $message['message_type'] === 'wholesale' ? 'عمده فروشی' : 'تماس با ما' ?></span></td><td><?= e($message['country'] ?: '—') ?></td><td><time datetime="<?= e($message['created_at']) ?>"><?= e(date('Y/m/d H:i', strtotime($message['created_at']))) ?></time></td><td><div class="table-actions"><a class="icon-action" href="<?= e(admin_url('/messages/view/' . (int) $message['id'])) ?>">مشاهده</a><form method="post" action="<?= e(admin_url('/messages')) ?>" data-confirm="آیا می‌خواهید این درخواست را حذف کنید؟"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="admin_action" value="delete_message"><input type="hidden" name="id" value="<?= e($message['id']) ?>"><button class="icon-action danger" type="submit">حذف</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php if (($messages['pages'] ?? 1) > 1): ?><nav class="admin-pagination" aria-label="صفحات پیام‌ها"><?php for ($page = 1; $page <= (int) $messages['pages']; $page++): ?><a class="<?= $page === (int) $messages['page'] ? 'is-current' : '' ?>" href="<?= e(admin_url('/messages?' . http_build_query(array_filter(array('q' => $query, 'type' => $type, 'page' => $page))))) ?>"><?= e($page) ?></a><?php endfor; ?></nav><?php endif; ?></section>
